message.content:
{
  "gate_token": "ZpVG0jhWtnbKb_oLpIoF_g",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unfolds a map at the edge of the ruined city.",
      "visual_description": "A tired mapmaker spreads a hand-drawn chart on a broken milestone; the shattered skyline of a royal city rises behind her under a bruised sky.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of obvious traps ahead.",
      "visual_description": "An oil lamp with a single glowing eye in its flame floats beside Mara, casting long warning shadows across cracked cobblestones.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scouts the broken castle gates.",
      "visual_description": "A small clockwork fox with blue glass eyes peers between iron portcullis bars, its key-wind tail ticking softly in the gloom.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver emerges from a cracked stained-glass window.",
      "visual_description": "A figure in a clear diving helmet steps out of a tall cathedral window as if from water, ripples still spreading across the colored glass.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team gathers beneath a tattered royal banner.",
      "visual_description": "Mara, the lamp, the fox, and the diver stand in a circle under a faded crimson banner half-torn from a stone arch.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "They find the sleeping tax collector slumped at a checkpoint.",
      "visual_description": "An official dozes on a ledger-book pillow inside a tollhouse, stamped papers fluttering from his sleeves while alarm bells ring distantly.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "Mara tries to question the snoring official.",
      "visual_description": "Mara leans over the dozing collector, brass compass dangling, while the oracle lamp hovers impatiently above his stamped sleeves.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The tin fox slips past an armored patrol.",
      "visual_description": "Clockwork paws tiptoe through the shadow of marching iron boots, only the fox's blue glass eyes glinting under a torchlit archway.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "A cursed tower looms, whispering temptations.",
      "visual_description": "A leaning black tower glows with green runes; the oracle lamp's eye narrows as it casts a warning beam across its locked doors.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "Glass Diver dives through a tall mirror in the plaza.",
      "visual_description": "The diver plunges headfirst into a freestanding silver mirror; his reflective coat scatters the city's broken lights into rainbows.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Inside the mirror, he finds the captive chamber.",
      "visual_description": "A glassy corridor opens into a vaulted cell of frozen reflections, where ghost-pale chains hover in mid-air around an empty throne.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "The fox carries a key back through a sewer grate.",
      "visual_description": "The tin fox squeezes through a rusted grate with an ornate brass key in its jaws, steam curling around its ticking tail.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Mara maps a route around the rumored dragon roost.",
      "visual_description": "Mara sketches a detour on parchment as enormous clawed shadows pass over distant rooftops; the lamp dims its eye to stay hidden.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "A magic door refuses to open without a price.",
      "visual_description": "A rune-carved door with a brass mouth demands payment; the team shoves the still-snoring tax collector forward, his stamps glowing.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The door accepts the official's stamped papers and opens.",
      "visual_description": "Glowing seals peel from the sleeping collector and stick to the door, which yawns open onto a moonlit courtyard of shattered statues.",
      "characters": ["sleeping_tax_collector", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "Townspeople flee as alarm bells finally crack the night.",
      "visual_description": "Frightened figures scatter through smoke-filled streets while Mara waves her team toward a narrow alley, compass swinging wildly.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "The team sprints onto the long stone bridge.",
      "visual_description": "Four figures race across an arched bridge over a black river; lantern light streaks behind them as the cursed city burns in the distance.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Safe across, they look back at the ruined city.",
      "visual_description": "On the far bank, Mara folds her map, the diver removes his helmet, the fox sits beside the glowing lamp, and the tax collector dozes on, finally rescued.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

